-- 0001_initial_schema.sql
--
-- Initial WikiHike schema. See ../schema.plan.md for the reasoning and
-- ../schema.asr.md for the review findings that shaped it.
--
-- Forward-only. Do not edit this file once applied; fix it with another migration.
--
-- Two conventions this file cannot enforce, both from the ASR:
--   * Order and paginate by created_at (server clock), never by started_at
--     (device clock, client-supplied, may be wrong or hostile).
--   * Proximity queries MUST include the 8 neighbour geohash cells. A bare
--     prefix match silently misses trailheads near any cell boundary.

BEGIN;

CREATE EXTENSION IF NOT EXISTS postgis;

-- Accounts -------------------------------------------------------------------
-- Reads are public; writes are not. Every write carries an author so that
-- moderation tooling has something to work with when it eventually exists.
-- Credential material (WebAuthn, Wikimedia OAuth subject) is deliberately absent
-- and belongs with the auth plan.

CREATE TABLE account (
    id           uuid PRIMARY KEY,
    display_name text NOT NULL CHECK (length(display_name) BETWEEN 1 AND 120),
    created_at   timestamptz NOT NULL DEFAULT now()
);

-- Trails ---------------------------------------------------------------------
-- trailhead_geohash is the indexed thing, not the path. Path geometry is stored
-- and shipped to the client; the database does not query against it.
--
-- The precision-5 and -6 prefixes are stored generated columns so proximity is an
-- indexed equality over 9 cells. Querying substr() or LIKE directly would either
-- miss the index or depend on collation, both of which fail quietly.
--   precision 5: cells ~4.9km square,   9-cell net ~15km across
--   precision 6: cells ~1.2km x 0.6km,  9-cell net ~3.7km x 1.8km
-- Adding another precision is one generated column and one index.

CREATE TABLE trail (
    id                  uuid PRIMARY KEY,
    name                text NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    trailhead_point     geography(Point, 4326) NOT NULL,

    -- Geohash base32: 0-9 and b-z excluding a, i, l, o.
    trailhead_geohash   text NOT NULL
                        CHECK (trailhead_geohash ~ '^[0-9b-hjkmnp-z]{12}$'),
    trailhead_geohash_5 text GENERATED ALWAYS AS (substr(trailhead_geohash, 1, 5)) STORED,
    trailhead_geohash_6 text GENERATED ALWAYS AS (substr(trailhead_geohash, 1, 6)) STORED,

    -- FK added below: composite and deferred. See ASR B1 and B2.
    current_revision_id uuid NOT NULL,
    created_at          timestamptz NOT NULL DEFAULT now()
);

-- Trail revisions ------------------------------------------------------------
-- Append-only. An edit inserts a revision and moves trail.current_revision_id.
-- Old revisions stay, for history, rollback, and the merge logic that is deferred
-- but whose schema shape is not.

CREATE TABLE trail_revision (
    id                 uuid PRIMARY KEY,
    trail_id           uuid NOT NULL REFERENCES trail (id) ON DELETE CASCADE,
    path               geography(LineString, 4326) NOT NULL,
    description        text NOT NULL DEFAULT '',
    author_id          uuid NOT NULL REFERENCES account (id) ON DELETE RESTRICT,
    parent_revision_id uuid,
    created_at         timestamptz NOT NULL DEFAULT now(),

    -- Target for the composite FKs that keep revision pointers inside one trail.
    UNIQUE (id, trail_id),

    -- A revision's parent must belong to the same trail. MATCH SIMPLE: a NULL
    -- parent_revision_id satisfies this, which is how the root revision works.
    FOREIGN KEY (parent_revision_id, trail_id)
        REFERENCES trail_revision (id, trail_id)
);

-- Deferred because the two tables reference each other and neither row can be
-- written first. Clients mint UUIDs, so a trail is inserted with its first
-- revision's id already set, the revision follows, and the check runs at COMMIT.
-- Composite so a trail cannot point at some other trail's revision.
ALTER TABLE trail
    ADD CONSTRAINT trail_current_revision_fk
    FOREIGN KEY (current_revision_id, id)
    REFERENCES trail_revision (id, trail_id)
    DEFERRABLE INITIALLY DEFERRED;

-- Hikes ----------------------------------------------------------------------
-- A hike is a GPS recording. Posting one does not propose an edit to any trail.
-- started_at and ended_at are device-reported and describe the walk. created_at
-- is the server clock and is what ordering and pagination use.

CREATE TABLE hike (
    id          uuid PRIMARY KEY,
    path        geography(LineString, 4326) NOT NULL,
    recorded_by uuid NOT NULL REFERENCES account (id) ON DELETE RESTRICT,
    started_at  timestamptz NOT NULL,
    ended_at    timestamptz NOT NULL,
    source      text NOT NULL CHECK (source IN ('recorded', 'uploaded')),
    created_at  timestamptz NOT NULL DEFAULT now(),

    CHECK (ended_at >= started_at)
);

-- Hike/trail bridge ----------------------------------------------------------
-- The user asserts which trails a hike covered. Nothing verifies it against the
-- recorded path; spatial validation is deferred.
--
-- Zero rows for a hike is legal and means an orphan hike: an unmapped route
-- recorded without creating a trail first. Every read path must handle it.
--
-- Keyed on (hike_id, ordinal), NOT (hike_id, trail_id): an out-and-back or a
-- loop that re-enters a connector covers the same trail more than once.

CREATE TABLE hike_trail (
    hike_id  uuid    NOT NULL REFERENCES hike (id) ON DELETE CASCADE,
    trail_id uuid    NOT NULL REFERENCES trail (id) ON DELETE RESTRICT,
    ordinal  integer NOT NULL CHECK (ordinal >= 0),

    PRIMARY KEY (hike_id, ordinal)
);

-- Indexes --------------------------------------------------------------------

-- Proximity. Queried as: trailhead_geohash_5 IN (cell, ...8 neighbours).
CREATE INDEX trail_geohash_5_idx ON trail (trailhead_geohash_5);
CREATE INDEX trail_geohash_6_idx ON trail (trailhead_geohash_6);

-- Revision history for one trail, newest first.
CREATE INDEX trail_revision_trail_id_created_at_idx
    ON trail_revision (trail_id, created_at DESC);

-- Attribution lookups, and the FK check on account deletes.
CREATE INDEX trail_revision_author_id_idx ON trail_revision (author_id);

-- One hiker's hikes, newest first. Ordered by server clock, see the header note.
CREATE INDEX hike_recorded_by_created_at_idx ON hike (recorded_by, created_at DESC);

-- Hikes on a given trail, and the FK check on trail deletes.
CREATE INDEX hike_trail_trail_id_idx ON hike_trail (trail_id);

COMMIT;
